        "originalUrl": "https://cdn.discordapp.com/attachments/1269536886586609695/1346014878871195658/dont_give_up.mp4?ex=6b01420a&is=6afff08a&hm=887da664a491f17a8e7b5292c8ffead6fab9d3a7764d08f479de06741d78af14&",
